import {weekDays,putAssignment,validateSchedule} from './lastplanner-daily.mjs';
import {sumarDias,esFecha} from './lastplanner-model.mjs';
export function filterPlanning(activities,restrictions,filters={}){return activities.filter(a=>!a.archivada&&!a.id.startsWith('demo-')&&(!filters.level||a.level===filters.level)&&(!filters.week||a.semana===filters.week)&&(!filters.especialidad||a.especialidad===filters.especialidad)&&(!filters.responsable||a.responsable===filters.responsable)&&(!filters.contratista||a.contratista===filters.contratista||a.planificacion?.schedule?.some(r=>r.contractor===filters.contratista))&&(!filters.team||a.planificacion?.schedule?.some(r=>r.teamId===filters.team))&&(!filters.status||a.fase===filters.status||a.verificacion?.resultado===filters.status)&&(!filters.restricted||restrictions.some(r=>a.restrictionIds.includes(r.id)&&!['Liberada','Cerrada'].includes(r.estado))));}
export function dailyItems(activities,date,filters={}){return activities.filter(a=>date>=a.inicioPlan&&date<=a.finPlan).map(activity=>({activity,date,assignments:(activity.planificacion?.schedule||[]).filter(r=>r.date===date&&(!filters.team||r.teamId===filters.team)&&(!filters.contratista||r.contractor===filters.contratista))})).sort((a,b)=>(a.activity.planificacion?.dayOrder?.[date]||0)-(b.activity.planificacion?.dayOrder?.[date]||0));}
export function moveAssignment(activity,id,date,{replace=false}={}){if(!esFecha(date)||date<activity.inicioPlan||date>activity.finPlan)throw Error('La jornada debe permanecer dentro del período. Usa Reprogramar actividad completa para cambiar el plazo.');const rows=activity.planificacion?.schedule||[],r=rows.find(r=>r.id===id);if(!r)throw Error('Asignación no disponible');if(date===r.date)return structuredClone(activity.planificacion);const collision=rows.find(x=>x.teamId===r.teamId&&x.date===date);if(collision&&!replace)throw Error('El equipo ya está programado en el destino. Confirma la actualización.');const schedule=putAssignment(rows.filter(x=>x.id!==r.id),{...r,date});validateSchedule(schedule,activity.inicioPlan,activity.finPlan);return {...activity.planificacion,schedule};}
export function shiftDraft(activity,start,end){if(activity.fase!=='borrador'||activity.grupo)throw Error('La reprogramación completa requiere un borrador independiente. Los compromisos publicados conservan su original; utiliza revisión autorizada o saldo.');if(!esFecha(start)||!esFecha(end)||end<start)throw Error('Período inválido');const delta=Math.round((Date.parse(start)-Date.parse(activity.inicioPlan))/864e5),schedule=(activity.planificacion?.schedule||[]).map(r=>({...r,date:sumarDias(r.date,delta)})).reduce((rows,r)=>putAssignment(rows,r),[]);validateSchedule(schedule,start,end);return {inicioPlan:start,finPlan:end,planificacion:{...activity.planificacion,schedule,dayOrder:Object.fromEntries(Object.entries(activity.planificacion?.dayOrder||{}).map(([date,order])=>[sumarDias(date,delta),order]))}};}
export function planningTotals(activities){return {activities:new Set(activities.map(a=>a.grupo?.id||a.id)).size,quantities:[...new Set(activities.map(a=>a.unidad))].map(unit=>({unit,quantity:activities.filter(a=>a.unidad===unit).reduce((n,a)=>n+a.cantidad,0)}))};}
export {weekDays};
